void go(BuildContext c, Widget p) => Navigator.of(c).push(MaterialPageRoute(builder: (_) => p));

class Img extends StatelessWidget {
  final String url; final double? w,h; final BorderRadius? r;
  const Img(this.url,{super.key,this.w,this.h,this.r});
  @override Widget build(BuildContext c){ final im=Image.network(url,width:w,height:h,fit:BoxFit.cover,errorBuilder:(_,__,___)=>Container(width:w,height:h,color:sand,alignment:Alignment.center,child:const Icon(Icons.home_work_outlined,size:38,color:muted))); return r==null?im:ClipRRect(borderRadius:r!,child:im); }
}

